import React from 'react'
import AWS from 'aws-sdk';
import Hashtag from './Hashtag'

export default function RenderData2() {

let receivedData = ''

const InputDownload = () => {
  AWS.config.update({
    accessKeyId: 'AKIA57MJGNPXRKXILUNK',
    secretAccessKey: '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',
  });

const handleClick = (e) => {
    e.preventDefault();
  };

  const handleDownload = () => {
    const s3 = new AWS.S3({region: 'us-east-2'});

    const params = {
      Bucket: 'processed-data-bucket-514-team6',
      Key: `data.csv`,
    };

    s3.getObject(params, (err, data) => {
      if (err) {
        console.log(err, err.stack);
      } else {
        receivedData = data.Body.toString();
        console.log(receivedData)
      }
    });

}
}
const textResponse = 'abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefgh';
let mapOfHashtags = new Map();
mapOfHashtags.set('#Example1', textResponse);
mapOfHashtags.set('#Example2', textResponse);
mapOfHashtags.set('#Example3', textResponse);
let listOfData = []
mapOfHashtags.forEach(function(val, key) {
    listOfData.push(<Hashtag hashtag={key} text={val} />);
})
  return (
    <div>
    {listOfData}
    <form className='bg-white my-4' onSubmit={handleClick}>
        <input
          type='submit'
          value='Download'
          className='btn btn-primary btn-block mt-3'
          onClick={handleDownload}
        />
      </form>
  </div>
  )
}
